import json
def C(title,scen,prompt,cues,target,en,can):
    return {"tier":"tier1","level":"B2","title":"Communicative Challenge: "+title,"scenario":scen,"prompt":prompt,"cues":cues,"target":target,"english":en,"canDo":can}
d={
'b2-salvadorhonduras-01':C('Whose Stelae?','You are Meg. You and Carlos are watching a documentary about Copán, and he asks you what makes the city special.','Tell Carlos what Copán is famous for.',['Say that Copán is a Maya city','Say whose stelae are famous'],'Copán es una ciudad maya cuyas estelas son famosas.','Copán is a Maya city whose stelae are famous.','I can say whose monuments or coasts I am talking about, with *cuyo*, *cuya*, *cuyos* and *cuyas*.'),
'b2-salvadorhonduras-02':C('What the Workers Said','You are Carlos. You and Meg are reading an article about northern Honduras, and she asks you about the banana strike of 1954.','Tell Meg what the workers said and how long the strike lasted, naming the source.',['Say what the workers said they wanted','Say how long the strike lasted, according to historians'],'Los trabajadores dijeron que querían mejores salarios. Según los historiadores, la huelga duró más de dos meses.','The workers said they wanted better wages. According to historians, the strike lasted more than two months.','I can report what people said, with *dijo que* and the right past tense.'),
'b2-salvadorhonduras-03':C('A Quiet Bishop?','You are Meg. You and Carlos are listening to a talk about El Salvador, and he asks you about Archbishop Romero.','Tell Carlos what people expected of Romero and what he did.',['Say what many people expected','Show the contrast with what Romero did'],'Muchos esperaban un obispo tranquilo; sin embargo, Romero habló por las víctimas.','Many expected a quiet bishop; however, Romero spoke for the victims.','I can show a contrast between two facts, with *sin embargo* and *no obstante*.'),
'b2-salvadorhonduras-04':C('Why They Left','You are Carlos. You and Meg are reading an article about migration from Honduras, and she asks you why so many people left in 1998.','Tell Meg why many Hondurans emigrated.',['Give the cause','Say what the cause destroyed'],'A raíz del huracán Mitch, muchas familias perdieron sus casas y sus cosechas.','As a result of Hurricane Mitch, many families lost their houses and their harvests.','I can give a cause with *debido a* and *a raíz de* and a noun.'),
'b2-salvadorhonduras-05':C('A Dated Fact','You are Meg. You and Carlos are following the news about Honduras, and he asks you about the 2025 election.','Tell Carlos who was declared the winner and when.',['Say who was declared the winner','Say the date'],'Nasry Asfura fue declarado ganador el 24 de diciembre de 2025.','Nasry Asfura was declared the winner on 24 December 2025.','I can say what was approved, declared or announced, with *ser* + past participle.'),
'b2-salvadorhonduras-consolidation':C('Review: El Salvador and Honduras','You are Carlos. You and Meg are planning a trip to Honduras, and she asks what you remember about Copán and the war in El Salvador.','Tell Meg one fact about each.',['Say whose stelae are famous in Copán','Say how long the war in El Salvador lasted, with a contrast'],'Copán es una ciudad cuyas estelas son famosas. La guerra duró doce años; sin embargo, en 1992 se firmó la paz.','Copán is a city whose stelae are famous. The war lasted twelve years; however, peace was signed in 1992.','I can say whose monuments or coasts I mean, with *cuyo*.')}
